// Core logic behind the "Demo-Projekte generieren" action on
// /admin/demo-daten (and behind scripts/generate-demo-listings.ts, a thin
// CLI wrapper around the same function). See shared.ts for the rationale
// behind using synthetic data instead of scraping real platforms.
//
// Project name/motto/"Wen wir suchen" are generated by combining
// independent word/sentence banks (see the *_STEMS, *_PART_A/B, SLOT_*
// constants below) rather than picked whole from one small fixed list —
// that's what makes every generated listing's text unique (see
// pickUniqueComposed in shared.ts) instead of the same handful of strings
// repeating once more than a few dozen listings exist. Each bank is a set of
// grammatically self-contained fragments (whole sentences, or whole
// compound-noun parts), so any recombination stays coherent — no
// mid-sentence word-swapping that could produce broken German grammar.
// "So leben wir" is the odd one out: a much longer (~200-400 word),
// deliberately absurd/over-the-top narrative composed in long-description.ts
// from per-stereotype (Handwerker, Yoga-Retreat, Sekte, ...) sentence banks,
// referencing whichever city/village the listing was placed in (see
// pickLocation() in shared.ts, which also spreads listings across small
// villages, not just big cities).

import {
  DEMO_EMAIL_DOMAIN,
  attachRandomPhoto,
  chance,
  jitterCoord,
  maybe,
  pick,
  pickLocation,
  pickMultiple,
  pickUniqueComposed,
  prisma,
  randomInt,
  randomName,
  randomPhone,
  STREET_NAMES,
} from "./shared";
import { buildLongDescriptionCandidate } from "./long-description";
import { setListingLocation } from "@/lib/geo";
import { generateListingSlug } from "@/lib/entity-slug";

