const WHO_WE_SEEK_SLOT_1 = [
  "Wir suchen Menschen, die gern mit anpacken und Verantwortung übernehmen.",
  "Am liebsten wären uns Mitbewohner:innen, die Gemeinschaft genauso schätzen wie ihren Rückzugsort.",
  "Uns ist wichtig, dass du Lust auf ein offenes Miteinander hast.",
  "Wer bei uns einzieht, sollte Tiere mögen, wir haben einige.",
  "Wir freuen uns über Menschen mit eigenen Ideen, die trotzdem gern gemeinsam entscheiden.",
  "Wichtig ist uns vor allem Offenheit, weniger eine bestimmte Lebensform.",
  "Wir suchen Leute, die auch mal über sich selbst lachen können.",
  "Uns ist es lieber, du bringst Neugier mit als ein perfektes Konzept.",
  "Wer gern gärtnert oder handwerkelt, ist bei uns sofort willkommen.",
  "Wir wünschen uns Mitbewohner:innen, die verlässlich sind, ohne verbissen zu sein.",
  "Am wichtigsten ist uns, dass du dich auf Gemeinschaft wirklich einlassen willst.",
  "Wir suchen jemanden, der gern Verantwortung teilt statt nur einfordert.",
];

const WHO_WE_SEEK_SLOT_2 = [
  "Vorerfahrung mit WG- oder Projektleben ist willkommen, aber kein Muss.",
  "Alter, Beruf oder Familienstand spielen bei uns keine große Rolle.",
  "Wichtiger als jede Checkliste ist uns ein gutes erstes Gespräch.",
  "Wir freuen uns über Menschen mit und ohne Kinder gleichermaßen.",
  "Ein Probewohnen vorab ist bei uns ausdrücklich möglich und erwünscht.",
  "Uns ist ein ehrliches Kennenlernen wichtiger als ein makelloser Lebenslauf.",
  "Wir sind offen für Menschen in ganz unterschiedlichen Lebensphasen.",
  "Ob introvertiert oder extrovertiert, bei uns findet beides seinen Platz.",
  "Wir legen Wert auf Zuverlässigkeit im Alltag, nicht auf Perfektion.",
  "Am Ende entscheiden wir gemeinsam, nicht nach starren Kriterien.",
  null,
  null,
];

// HTML (matching what RichTextField's reduced editor can produce, see
// sanitizeRichText()'s tag allowlist) — a two-item bullet list when both
// slots roll a sentence, otherwise a single paragraph, since this feeds the
// same `whoWeAreLooking` field a real submission would.
function buildWhoWeSeekCandidate(): string {
  const second = pick(WHO_WE_SEEK_SLOT_2);
  const first = pick(WHO_WE_SEEK_SLOT_1);
  return second ? `<ul><li>${first}</li><li>${second}</li></ul>` : `<p>${first}</p>`;
}

async function ensureDemoOwners(count: number): Promise<string[]> {
  const ids: string[] = [];
  for (let i = 0; i < count; i++) {
    const email = `demo-owner-${i}@${DEMO_EMAIL_DOMAIN}`;
    const user = await prisma.user.upsert({
      where: { email },
      update: {},
      create: { email, name: randomName() },
    });
    ids.push(user.id);
  }
  return ids;
}

export type GenerateProgress = (current: number, total: number, message: string) => void;

/**
 * Creates `count` (clamped 1-100) synthetic, clearly-fake Wohnprojekt
 * listings with a wide randomized spread of attributes, categories, address/
 * geo data and 1-2 photos each. Every created row has `isDemo: true`, and
 * every project name/motto/"So leben wir"/"Wen wir suchen" is unique both
 * within this batch and against demo listings already in the database (see
 * pickUniqueComposed in shared.ts).
 */
export async function generateDemoListings(
  count: number,
  onProgress?: GenerateProgress,
): Promise<{ created: number }> {
  const clamped = Math.min(100, Math.max(1, Math.floor(count)));

  const ownerIds = await ensureDemoOwners(8);

  const [categories, listingGroups, existingDemoListings] = await Promise.all([
    prisma.listingCategory.findMany(),
    prisma.attributeGroup.findMany({
      where: { appliesTo: "LISTING" },
      include: { options: true },
    }),
    prisma.listing.findMany({
      where: { isDemo: true },
      select: { projectName: true, motto: true, howWeLive: true, whoWeAreLooking: true },
    }),
  ]);

  if (categories.length === 0 || listingGroups.length === 0) {
    throw new Error(
      "Keine ListingCategory/AttributeGroup-Daten gefunden. Bitte zuerst `pnpm db:seed` ausführen.",
    );
  }

  const usedNames = new Set(existingDemoListings.map((l) => l.projectName));
  const usedMottos = new Set(
    existingDemoListings.map((l) => l.motto).filter((v): v is string => Boolean(v)),
  );
  const usedHowWeLive = new Set(
    existingDemoListings.map((l) => l.howWeLive).filter((v): v is string => Boolean(v)),
  );
  const usedWhoWeSeek = new Set(
    existingDemoListings.map((l) => l.whoWeAreLooking).filter((v): v is string => Boolean(v)),
  );

  for (let i = 0; i < clamped; i++) {
    const { location: city, isVillage } = pickLocation();
    const projectName = pickUniqueComposed(buildProjectNameCandidate, usedNames);
    const motto = chance(0.85) ? pickUniqueComposed(buildMottoCandidate, usedMottos) : null;
    const howWeLive = chance(0.8)
      ? pickUniqueComposed(() => buildLongDescriptionCandidate(city.city, isVillage), usedHowWeLive)
      : null;
    const whoWeAreLooking = chance(0.75)
      ? pickUniqueComposed(buildWhoWeSeekCandidate, usedWhoWeSeek)
      : null;

    const hasStreet = chance(0.7);
    const isTemporary = chance(0.25);
    const groupSizeCurrent = maybe(randomInt(1, 14), 0.85);
    const publishedDaysAgo = randomInt(0, 200);

    // Realistic search periods: mostly a start date plus a week- or
    // month-length window, occasionally just a start date with no end
    // (an open-ended "looking from this date onward"), sometimes no period
    // at all (not currently searching for a specific timeframe).
    let searchPeriodStart: Date | null = null;
    let searchPeriodEnd: Date | null = null;
    if (chance(0.7)) {
      searchPeriodStart = new Date(Date.now() + randomInt(-10, 30) * 24 * 60 * 60 * 1000);
      const periodLength = pick(["week", "week", "month", "month", "open"] as const);
      if (periodLength === "week") {
        searchPeriodEnd = new Date(searchPeriodStart.getTime() + randomInt(5, 9) * 24 * 60 * 60 * 1000);
      } else if (periodLength === "month") {
        searchPeriodEnd = new Date(searchPeriodStart.getTime() + randomInt(26, 35) * 24 * 60 * 60 * 1000);
      }
      // "open" leaves searchPeriodEnd null — a start date with no end.
    }

    const listing = await prisma.listing.create({
      data: {
        status: "PUBLISHED",
        isDemo: true,
        publishedAt: new Date(Date.now() - publishedDaysAgo * 24 * 60 * 60 * 1000),
        projectName,
        slug: await generateListingSlug(projectName),
        createdById: pick(ownerIds),
        motto,
        howWeLive,
        whoWeAreLooking,
        country: city.country,
        state: city.state,
        postalCode: city.postalCode,
        city: city.city,
        street: hasStreet ? pick(STREET_NAMES) : null,
        houseNumber: hasStreet ? String(randomInt(1, 140)) : null,
        regionDescription: hasStreet ? null : `Großraum ${city.city}`,
        latitude: jitterCoord(city.lat),
        longitude: jitterCoord(city.lng),
        contactName: maybe(randomName(), 0.5),
        contactEmail: maybe(`kontakt${randomInt(1, 999)}@${DEMO_EMAIL_DOMAIN}`, 0.5),
        contactPhone: maybe(randomPhone(), 0.4),
        isTemporary,
        moveInDate: maybe(new Date(Date.now() + randomInt(-30, 180) * 24 * 60 * 60 * 1000), 0.5),
        minStayDays: isTemporary ? randomInt(7, 60) : null,
        maxStayDays: isTemporary ? randomInt(60, 365) : null,
        searchPeriodStart,
        searchPeriodEnd,
        groupSizeCurrent,
        groupSizePlanned: maybe(randomInt(groupSizeCurrent ?? 1, 20), 0.4),
        freeSpots: maybe(randomInt(0, 5), 0.6),
        desiredAgeMin: maybe(randomInt(18, 45), 0.4),
        desiredAgeMax: maybe(randomInt(45, 99), 0.4),
        costOneTime: maybe(randomInt(0, 5000), 0.35),
        costMonthly: maybe(randomInt(150, 1200), 0.7),
        categories: {
          create: pickMultiple(categories, 3).map((c) => ({ categoryId: c.id })),
        },
      },
    });

    // One attribute option per group (respecting allowMultiple), mixed
    // wildly across all groups so every filter combination gets exercised.
    for (const group of listingGroups) {
      const selected = group.allowMultiple
        ? pickMultiple(group.options, 3)
        : chance(0.9)
          ? [pick(group.options)]
          : [];
      for (const option of selected) {
        await prisma.listingAttributeOption.create({
          data: { listingId: listing.id, optionId: option.id },
        });
      }
    }

    await setListingLocation(listing.id, listing.latitude, listing.longitude);

    // Three to six photos per listing, enough to exercise a real gallery.
    const photoCount = randomInt(3, 6);
    for (let p = 0; p < photoCount; p++) {
      const stored = await attachRandomPhoto(`listings/${listing.id}`);
      if (!stored) continue;
      await prisma.media.create({
        data: {
          listingId: listing.id,
          type: "PHOTO",
          storageKey: stored.storageKey,
          thumbnailKey: stored.thumbnailKey,
          position: p,
          uploadedById: listing.createdById,
        },
      });
    }

    onProgress?.(i + 1, clamped, `${projectName} (${city.city})`);
  }

  return { created: clamped };
}
